// n8n Code Node (JavaScript)
// Entrada: items[] con campos: Pedido (string JSON u objeto), Total, Estatus, Nombre, Telefono, Correo, created_at
// Salida: un item por destinatario con { to, subject, html }

function currencyMXN(n) {
  const num = Number(n);
  if (Number.isNaN(num)) return String(n ?? '');
  return num.toLocaleString('es-MX', { style: 'currency', currency: 'MXN', maximumFractionDigits: 2 });
}

function esc(s) {
  return String(s ?? '')
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Normaliza estatus y estilos "semáforo"
function statusMeta(estatus) {
  const key = String(estatus || '').trim().toLowerCase();
  if (key === 'activo') {
    return { label: 'Activa', color: '#16a34a', bg: '#dcfce7', rowBg: '#ecfdf5' };
  }
  if (key === 'por vencer') {
    return { label: 'Por vencer', color: '#b45309', bg: '#fef3c7', rowBg: '#fffbeb' };
  }
  if (key === 'vencido' || key === 'vencida') {
    return { label: 'Vencida', color: '#b91c1c', bg: '#fee2e2', rowBg: '#fef2f2' };
  }
  return { label: estatus || '—', color: '#374151', bg: '#f3f4f6', rowBg: '#ffffff' };
}

// Soporta distintos formatos de productos y evita "undefined"
function productosResumen(pedidoIn) {
  let obj = pedidoIn;
  try { if (typeof obj === 'string') obj = JSON.parse(obj); } catch { /* ignore */ }
  const prods = Array.isArray(obj?.productos) ? obj.productos : [];
  if (!prods.length) return '—';

  const toQty = (p) => {
    if (p.cantidad != null) return p.cantidad;
    if (p.qty != null) return p.qty;
    if (p.kilos != null) return p.kilos;
    return '';
  };

  return prods.map(p => {
    const nombre = p.nombre ?? p.producto ?? 'Producto';
    const qty = toQty(p);
    return `${nombre}${qty !== '' ? ` (x${qty})` : ''}`;
  }).join(', ');
}

// === FILTRO DE MES ACTUAL (America/Mexico_City) ===
function esDelMesActual(fechaStr) {
  if (!fechaStr) return false;
  // "Ahora" en zona MX
  const ahoraLocalStr = new Date().toLocaleString('en-US', { timeZone: 'America/Mexico_City' });
  const ahora = new Date(ahoraLocalStr);
  // Intentar parsear created_at; si viene "YYYY-MM-DD HH:mm:ss", también lo toma.
  const f = new Date(fechaStr);
  if (isNaN(f)) return false;
  return f.getFullYear() === ahora.getFullYear() && f.getMonth() === ahora.getMonth();
}

// === PLANTILLA CON CSS INLINE ===
function buildHTML(nombre, correo, pedidos) {
  // Contadores y suma
  const counts = { activo: 0, 'por vencer': 0, vencido: 0 };
  let totalSuma = 0;

  const rows = pedidos.map((p, idx) => {
    const meta = statusMeta(p.Estatus);
    const totalNum = Number(p.Total);
    if (!Number.isNaN(totalNum)) totalSuma += totalNum;

    // Contar por estatus normalizado
    const k = String(p.Estatus || '').trim().toLowerCase();
    if (k in counts) counts[k]++;

    return `
      <tr>
        <td style="padding:12px;border-bottom:1px solid #e5e7eb;font:14px/20px system-ui, -apple-system, Segoe UI, Roboto; background:${meta.rowBg}">${idx + 1}</td>
        <td style="padding:12px;border-bottom:1px solid #e5e7eb;font:14px/20px system-ui, -apple-system, Segoe UI, Roboto; background:${meta.rowBg}">
          <span style="display:inline-block;padding:4px 8px;border-radius:999px;border:1px solid rgba(0,0,0,0.06);background:${meta.bg};color:${meta.color};font:12px/16px system-ui, -apple-system, Segoe UI, Roboto;">
            ${esc(meta.label)}
          </span>
        </td>
        <td style="padding:12px;border-bottom:1px solid #e5e7eb;font:14px/20px system-ui, -apple-system, Segoe UI, Roboto; white-space:nowrap; background:${meta.rowBg}">${currencyMXN(p.Total)}</td>
        <td style="padding:12px;border-bottom:1px solid #e5e7eb;font:14px/20px system-ui, -apple-system, Segoe UI, Roboto; background:${meta.rowBg}">${esc(productosResumen(p.Pedido))}</td>
      </tr>
    `;
  }).join('');

  const hoy = new Date().toLocaleDateString('es-MX', { year: 'numeric', month: 'long', day: '2-digit' });

  return `<!DOCTYPE html>
<html lang="es">
<body style="margin:0;padding:0;background:#f3f4f6;">
  <table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="background:#f3f4f6;">
    <tr>
      <td align="center" style="padding:24px 12px;">
        <table width="720" cellspacing="0" cellpadding="0" border="0" style="max-width:720px;width:100%;background:#ffffff;border:1px solid #e5e7eb;border-radius:12px;overflow:hidden;">
          <tr>
            <td style="padding:24px;border-bottom:1px solid #e5e7eb;background:#faf5ff;">
              <div style="font:20px/24px system-ui,-apple-system,Segoe UI,Roboto;font-weight:700;color:#111827;">Resumen de facturas del mes</div>
              <div style="margin-top:6px;font:14px/20px system-ui,-apple-system,Segoe UI,Roboto;color:#6b7280;">Enviado el ${esc(hoy)} · ${esc(correo)}</div>
            </td>
          </tr>
          <tr>
            <td style="padding:20px 24px 0;font:15px/22px system-ui,-apple-system,Segoe UI,Roboto;color:#111827;">
              Hola <strong style="color:#7c3aed;">${esc(nombre)}</strong>, aquí Rafita de <span style="font-weight:700;">Grupo D'Linaje</span>.<br/>
              Te comparto el resumen de tus facturas de este mes.
            </td>
          </tr>
          <tr>
            <td style="padding:8px 24px 16px;">
              <div style="display:inline-block;margin:8px 8px 0 0;padding:6px 10px;border-radius:999px;background:#f3f4f6;border:1px solid #e5e7eb;font:12px/16px system-ui,-apple-system,Segoe UI,Roboto;color:#374151;">Activas: ${counts.activo}</div>
              <div style="display:inline-block;margin:8px 8px 0 0;padding:6px 10px;border-radius:999px;background:#f3f4f6;border:1px solid #e5e7eb;font:12px/16px system-ui,-apple-system,Segoe UI,Roboto;color:#374151;">Por vencer: ${counts['por vencer']}</div>
              <div style="display:inline-block;margin:8px 8px 0 0;padding:6px 10px;border-radius:999px;background:#f3f4f6;border:1px solid #e5e7eb;font:12px/16px system-ui,-apple-system,Segoe UI,Roboto;color:#374151;">Vencidas: ${counts.vencido}</div>
              <div style="display:inline-block;margin:8px 8px 0 0;padding:6px 10px;border-radius:999px;background:#f3f4f6;border:1px solid #e5e7eb;font:12px/16px system-ui,-apple-system,Segoe UI,Roboto;color:#111827;">Total acumulado: <strong>${currencyMXN(totalSuma)}</strong></div>
            </td>
          </tr>
          <tr>
            <td style="padding:12px 16px 24px;">
              <table role="table" width="100%" cellspacing="0" cellpadding="0" border="0" style="border:1px solid #e5e7eb;border-radius:8px;overflow:hidden;">
                <thead>
                  <tr>
                    <th align="left" style="background:#f3f4f6;color:#374151;font:12px/16px system-ui,-apple-system,Segoe UI,Roboto;padding:10px 12px;border-bottom:1px solid #e5e7eb;width:40px;">#</th>
                    <th align="left" style="background:#f3f4f6;color:#374151;font:12px/16px system-ui,-apple-system,Segoe UI,Roboto;padding:10px 12px;border-bottom:1px solid #e5e7eb;width:140px;">Estatus</th>
                    <th align="left" style="background:#f3f4f6;color:#374151;font:12px/16px system-ui,-apple-system,Segoe UI,Roboto;padding:10px 12px;border-bottom:1px solid #e5e7eb;width:140px;">Total</th>
                    <th align="left" style="background:#f3f4f6;color:#374151;font:12px/16px system-ui,-apple-system,Segoe UI,Roboto;padding:10px 12px;border-bottom:1px solid #e5e7eb;">Productos</th>
                  </tr>
                </thead>
                <tbody>
                  ${rows}
                </tbody>
              </table>
            </td>
          </tr>
          <tr>
            <td style="border-top:1px solid #e5e7eb;padding:16px 24px 24px;font:12px/18px system-ui,-apple-system,Segoe UI,Roboto;color:#6b7280;">
              © ${new Date().getFullYear()} <span style="font-weight:700;color:#111827;">Carnicería San Rafa</span> · Sucursal Centro · Tel. 555-123-4567 · Horario: Lun-Dom 8:00–19:00.
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>
</body>
</html>`;
}

// === MAIN ===

// 1) Filtrar por mes actual
const filtrados = items
  .map(i => i.json || {})
  .filter(row => esDelMesActual(row.created_at));

// 2) Agrupar por correo
const byEmail = new Map();
for (const row of filtrados) {
  const correo = String(row.Correo || '').trim().toLowerCase() || 'sin_correo@local';
  if (!byEmail.has(correo)) byEmail.set(correo, []);
  byEmail.get(correo).push(row);
}

// 3) Construir salida (un item por destinatario) — si un correo no tiene pedidos tras el filtro, no se crea item
const out = [];
for (const [correo, pedidos] of byEmail.entries()) {
  if (!pedidos.length) continue;
  const nombre = pedidos[0]?.Nombre || 'Cliente';
  const subject = `Tus facturas del mes - Grupo D'Linaje`;
  const html = buildHTML(nombre, correo, pedidos);
  out.push({ json: { to: correo, subject, html, nombre } });
}

return out;
